29:     let g = open(5, 5);
30:     let four = astar_bool_grid(5, 5, &g, (0, 0), (3, 3)).expect("reachable");
31:     let eight = astar_bool_grid_8(5, 5, &g, (0, 0), (3, 3)).expect("reachable");
32:     assert_eq!(four.len(), 6, "4-connected baseline");
33:     assert_eq!(eight.len(), 3, "8-connected should cut the corner");
